<script setup lang="ts">
import { onLaunch, onShow, onHide } from '@dcloudio/uni-app'
import { useAudioStore } from '@/stores/audio'

// 应用启动时执行一次
onLaunch(() => {
  console.log('英语听力小程序启动')
  // 初始化微信云开发：音频地址是云文件 ID（cloud://），播放器解析它需要先初始化云环境
  const w = typeof wx !== 'undefined' ? (wx as any) : undefined
  if (w && w.cloud) {
    w.cloud.init({ env: 'cloud1-d8ghwimjk70dd788d', traceUser: true })
    // 预热云函数容器：启动时先打一次空请求，等首页真正要换封面/音频地址时容器已是热的，
    // 省掉第一次调用的 1~3 秒冷启动（空 fileIDs 在云函数里直接返回，不查库、几乎零成本）
    try {
      const p = w.cloud.callFunction({ name: 'getAudioUrl', data: { fileIDs: [] } })
      if (p && typeof p.catch === 'function') p.catch(() => {})
    } catch {
      // 预热失败不影响正常功能
    }
  }
})

onShow(() => {
  // 从后台切回前台
})

onHide(() => {
  // 从前台切入后台即停掉音频：微信右侧的音频悬浮窗依赖有效的后台播放会话，
  // 之前只在详情页 onUnload 里停，切后台/退小程序时不会触发，悬浮窗就一直挂着。
  // 代价：切出去或锁屏后不再后台继续播；如需后台播放再改回来。
  try {
    useAudioStore().stop()
  } catch {
    // store 未初始化时忽略
  }
})
</script>

